var _danPxShapes = { square: 0, circle: 1, triangle: 2, diamond: 3 };
var _danPxMaxTaps = 10;

function _danPxToLinear(hex) {
    var color = (hex || "#03a9f4").replace("#", "");
    while (color.length < 6) {
        color += "0";
    }
    var r = parseInt(color.slice(0, 2), 16) / 255;
    var g = parseInt(color.slice(2, 4), 16) / 255;
    var b = parseInt(color.slice(4, 6), 16) / 255;
    function toLinear(v) {
        return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    }
    return [toLinear(r), toLinear(g), toLinear(b)];
}

var _danPxVert = "#version 300 es\nin vec2 aPos;\nvoid main(){gl_Position=vec4(aPos,0.0,1.0);}";

var _danPxFrag = [
    "#version 300 es",
    "precision highp float;",
    "uniform vec3 uTint;",
    "uniform vec2 uSize;",
    "uniform float uClock;",
    "uniform float uCellSize;",
    "uniform float uFrequency;",
    "uniform float uFill;",
    "uniform float uCellJitter;",
    "uniform int uWavesOn;",
    "uniform float uWaveSpeed;",
    "uniform float uWaveWidth;",
    "uniform float uWaveForce;",
    "uniform float uFadeY;",
    "uniform float uFadeX;",
    "uniform float uGrain;",
    "uniform int uCellShape;",
    "#define MAX_TAPS 10",
    "uniform vec2 uTapCoords[MAX_TAPS];",
    "uniform float uTapTimes[MAX_TAPS];",
    "out vec4 fragColor;",
    "const float _bayerMat[64]=float[64](",
    "  0.0,48.0,12.0,60.0, 3.0,51.0,15.0,63.0,",
    "  32.0,16.0,44.0,28.0,35.0,19.0,47.0,31.0,",
    "  8.0,56.0, 4.0,52.0,11.0,59.0, 7.0,55.0,",
    "  40.0,24.0,36.0,20.0,43.0,27.0,39.0,23.0,",
    "  2.0,50.0,14.0,62.0, 1.0,49.0,13.0,61.0,",
    "  34.0,18.0,46.0,30.0,33.0,17.0,45.0,29.0,",
    "  10.0,58.0, 6.0,54.0, 9.0,57.0, 5.0,53.0,",
    "  42.0,26.0,38.0,22.0,41.0,25.0,37.0,21.0);",
    "float dither8(vec2 coord){",
    "  ivec2 c=ivec2(mod(floor(coord),8.0));",
    "  return _bayerMat[c.y*8+c.x]/64.0-0.5;",
    "}",
    "#define NOISE_ITERS 5",
    "#define NOISE_LAC 1.25",
    "#define NOISE_GAIN 1.0",
    "float rand1(float n){return fract(sin(n*127.1)*37852.7491);}",
    "float valNoise3(vec3 p){",
    "  vec3 ip=floor(p);vec3 fp=fract(p);",
    "  vec3 k=vec3(1.0,63.0,131.0);",
    "  float n000=rand1(dot(ip+vec3(0,0,0),k));",
    "  float n100=rand1(dot(ip+vec3(1,0,0),k));",
    "  float n010=rand1(dot(ip+vec3(0,1,0),k));",
    "  float n110=rand1(dot(ip+vec3(1,1,0),k));",
    "  float n001=rand1(dot(ip+vec3(0,0,1),k));",
    "  float n101=rand1(dot(ip+vec3(1,0,1),k));",
    "  float n011=rand1(dot(ip+vec3(0,1,1),k));",
    "  float n111=rand1(dot(ip+vec3(1,1,1),k));",
    "  vec3 w=fp*fp*fp*(fp*(fp*6.0-15.0)+10.0);",
    "  float x00=mix(n000,n100,w.x);float x10=mix(n010,n110,w.x);",
    "  float x01=mix(n001,n101,w.x);float x11=mix(n011,n111,w.x);",
    "  float y0=mix(x00,x10,w.y);float y1=mix(x01,x11,w.y);",
    "  return mix(y0,y1,w.z)*2.0-1.0;",
    "}",
    "float fractalNoise(vec2 uv,float t){",
    "  vec3 p=vec3(uv*uFrequency,t);float amp=1.0;float freq=1.0;float sum=1.0;",
    "  for(int i=0;i<NOISE_ITERS;++i){sum+=amp*valNoise3(p*freq);freq*=NOISE_LAC;amp*=NOISE_GAIN;}",
    "  return sum*0.5+0.5;",
    "}",
    "float shapeDisc(vec2 p,float cov){",
    "  float radius=sqrt(cov)*0.25;",
    "  float dist=distance(p,vec2(0.5))-radius;",
    "  float hw=0.5*fwidth(dist);",
    "  return cov*(1.0-smoothstep(-hw,hw,dist+dist));",
    "}",
    "float shapeTri(vec2 p,vec2 id,float cov){",
    "  float flip=step(0.5,mod(id.x+id.y,2.0));",
    "  p.x=mix(p.x,1.0-p.x,flip);",
    "  float r=sqrt(cov);float d=p.y-r*(1.0-p.x);float aa=fwidth(d);",
    "  return cov*clamp(0.5-d/aa,0.0,1.0);",
    "}",
    "float shapeRhombus(vec2 p,float cov){",
    "  float r=sqrt(cov)*0.564;",
    "  vec2 d=abs(p-vec2(0.49));",
    "  return step(d.x+d.y,r);",
    "}",
    "void main(){",
    "  float cellSz=uCellSize;",
    "  vec2 fragCoord=gl_FragCoord.xy-uSize*.5;",
    "  float aspect=uSize.x/uSize.y;",
    "  vec2 cellId=floor(fragCoord/cellSz);",
    "  vec2 cellUV=fract(fragCoord/cellSz);",
    "  float groupSize=8.0*cellSz;",
    "  vec2 groupId=floor(fragCoord/groupSize);",
    "  vec2 groupCoord=groupId*groupSize;",
    "  vec2 uv=groupCoord/uSize*vec2(aspect,1.0);",
    "  float base=fractalNoise(uv,uClock*0.05);",
    "  base=base*0.5-0.65;",
    "  float feed=base+(uFill-0.5)*0.3;",
    "  if(uWavesOn==1){",
    "    for(int i=0;i<MAX_TAPS;++i){",
    "      vec2 pos=uTapCoords[i];if(pos.x<0.0)continue;",
    "      float gSz=8.0*cellSz;",
    "      vec2 cuv=(((pos-uSize*.5-gSz*.5)/uSize))*vec2(aspect,1.0);",
    "      float t=max(uClock-uTapTimes[i],0.0);",
    "      float r=distance(uv,cuv);",
    "      float waveR=uWaveSpeed*t;",
    "      float ring=exp(-pow((r-waveR)/uWaveWidth,2.0));",
    "      float atten=exp(-1.0*t)*exp(-10.0*r);",
    "      feed=max(feed,ring*atten*uWaveForce);",
    "    }",
    "  }",
    "  float bayer=dither8(fragCoord/uCellSize);",
    "  float bw=step(0.5,feed+bayer);",
    "  float h=fract(sin(dot(floor(fragCoord/uCellSize),vec2(113.7,269.3)))*29571.8634);",
    "  float jitterScale=1.0+(h-0.5)*uCellJitter;",
    "  float coverage=bw*jitterScale;",
    "  float M;",
    "  if(uCellShape==1)M=shapeDisc(cellUV,coverage);",
    "  else if(uCellShape==2)M=shapeTri(cellUV,cellId,coverage);",
    "  else if(uCellShape==3)M=shapeRhombus(cellUV,coverage);",
    "  else M=coverage;",
    "  if(uFadeY>0.0||uFadeX>0.0){",
    "    vec2 norm=gl_FragCoord.xy/uSize;",
    "    float fadeV=uFadeY>0.0?smoothstep(0.0,uFadeY,min(norm.y,1.0-norm.y)):1.0;",
    "    float fadeH=uFadeX>0.0?smoothstep(0.0,uFadeX,min(norm.x,1.0-norm.x)):1.0;",
    "    M*=fadeH*fadeV;",
    "  }",
    "  vec3 lo=uTint*12.92;",
    "  vec3 hi=1.055*pow(uTint,vec3(1.0/2.4))-0.055;",
    "  vec3 srgb=mix(lo,hi,step(vec3(0.0031308),uTint));",
    "  if(uGrain>0.0){",
    "    float nv=fract(sin(dot(floor(gl_FragCoord.xy)+vec2(floor(uClock*60.0)),vec2(113.7,269.3)))*29571.8634);",
    "    srgb+=vec3((nv-0.5)*uGrain);",
    "  }",
    "  fragColor=vec4(srgb,M);",
    "}"
].join("\n");

function dancepad_pixels(){document.querySelectorAll(".dan-pixels").forEach(function(element){if(element._danPxCtx){try{if(element._danPxCtx.raf){cancelAnimationFrame(element._danPxCtx.raf)}
if(element._danPxCtx.ro){element._danPxCtx.ro.disconnect()}
if(element._danPxCtx.onDown){element._danPxCtx.canvas.removeEventListener("pointerdown",element._danPxCtx.onDown)}}catch(e){}
element._danPxCtx=null}
var canvas=element.querySelector(".dan-pixels__canvas");if(!canvas){element.removeAttribute("data-flickering");return}
var gl=canvas.getContext("webgl2",{alpha:!0,antialias:!0,premultipliedAlpha:!1});if(!gl){element.removeAttribute("data-flickering");return}
function compile(source,type){var shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS)){gl.deleteShader(shader);return null}
return shader}
var vertexShader=compile(_danPxVert,gl.VERTEX_SHADER);var fragmentShader=compile(_danPxFrag,gl.FRAGMENT_SHADER);if(!vertexShader||!fragmentShader){element.removeAttribute("data-flickering");return}
var program=gl.createProgram();gl.attachShader(program,vertexShader);gl.attachShader(program,fragmentShader);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS)){element.removeAttribute("data-flickering");return}
gl.useProgram(program);var posLoc=gl.getAttribLocation(program,"aPos");var positionBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,positionBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);gl.enableVertexAttribArray(posLoc);gl.vertexAttribPointer(posLoc,2,gl.FLOAT,!1,0,0);var colorHex=element.getAttribute("data-color")||"#03a9f4";var colorLin=_danPxToLinear(colorHex);var shapeType=_danPxShapes[element.getAttribute("data-shape")]||0;var pixelSize=parseFloat(element.getAttribute("data-pixel-size")||5);var scale=parseFloat(element.getAttribute("data-scale")||2);var density=parseFloat(element.getAttribute("data-density")||1);var jitter=parseFloat(element.getAttribute("data-jitter")||0);var edgeFade=parseFloat(element.getAttribute("data-edge-fade")||0.5);var sideFade=parseFloat(element.getAttribute("data-side-fade")||0);var speed=parseFloat(element.getAttribute("data-speed")||0.5);var noiseAmount=parseFloat(element.getAttribute("data-noise")||0);var ripples=element.getAttribute("data-ripples")==="1"?1:0;var rippleSpeed=parseFloat(element.getAttribute("data-ripple-speed")||0.3);var rippleThickness=parseFloat(element.getAttribute("data-ripple-thickness")||0.1);var rippleIntensity=parseFloat(element.getAttribute("data-ripple-intensity")||1);var uSize=gl.getUniformLocation(program,"uSize");var uClock=gl.getUniformLocation(program,"uClock");var uTint=gl.getUniformLocation(program,"uTint");var uCellShape=gl.getUniformLocation(program,"uCellShape");var uCellSize=gl.getUniformLocation(program,"uCellSize");var uFrequency=gl.getUniformLocation(program,"uFrequency");var uFill=gl.getUniformLocation(program,"uFill");var uCellJitter=gl.getUniformLocation(program,"uCellJitter");var uFadeY=gl.getUniformLocation(program,"uFadeY");var uFadeX=gl.getUniformLocation(program,"uFadeX");var uGrain=gl.getUniformLocation(program,"uGrain");var uWavesOn=gl.getUniformLocation(program,"uWavesOn");var uWaveSpeed=gl.getUniformLocation(program,"uWaveSpeed");var uWaveWidth=gl.getUniformLocation(program,"uWaveWidth");var uWaveForce=gl.getUniformLocation(program,"uWaveForce");var uTapCoords=gl.getUniformLocation(program,"uTapCoords");var uTapTimes=gl.getUniformLocation(program,"uTapTimes");gl.uniform3fv(uTint,colorLin);gl.uniform1i(uCellShape,shapeType);gl.uniform1f(uFrequency,scale);gl.uniform1f(uFill,density);gl.uniform1f(uCellJitter,jitter);gl.uniform1f(uFadeY,edgeFade);gl.uniform1f(uFadeX,sideFade);gl.uniform1f(uGrain,noiseAmount);gl.uniform1i(uWavesOn,ripples);gl.uniform1f(uWaveSpeed,rippleSpeed);gl.uniform1f(uWaveWidth,rippleThickness);gl.uniform1f(uWaveForce,rippleIntensity);var tapCoordsArr=new Float32Array(_danPxMaxTaps*2);var tapTimesArr=new Float32Array(_danPxMaxTaps);for(var i=0;i<_danPxMaxTaps*2;i+=1){tapCoordsArr[i]=-1}
gl.uniform2fv(uTapCoords,tapCoordsArr);gl.uniform1fv(uTapTimes,tapTimesArr);var tapIndex=0;var dpr=Math.min(window.devicePixelRatio||1,2);var timeOffset=Math.random()*1000;var startTime=performance.now();gl.clearColor(0,0,0,0);function resize(){var rect=element.getBoundingClientRect();if(rect.width<1||rect.height<1){return}
var width=Math.round(rect.width*dpr);var height=Math.round(rect.height*dpr);canvas.width=width;canvas.height=height;gl.viewport(0,0,width,height);gl.uniform2f(uSize,width,height);gl.uniform1f(uCellSize,pixelSize*dpr)}
resize();var resizeObserver=new ResizeObserver(function(){resize()});resizeObserver.observe(element);var onPointerDown=function(event){var rect=canvas.getBoundingClientRect();var sx=canvas.width/rect.width;var sy=canvas.height/rect.height;var fx=(event.clientX-rect.left)*sx;var fy=(rect.height-(event.clientY-rect.top))*sy;var t=timeOffset+((performance.now()-startTime)/1000)*speed;tapCoordsArr[tapIndex*2]=fx;tapCoordsArr[tapIndex*2+1]=fy;tapTimesArr[tapIndex]=t;tapIndex=(tapIndex+1)%_danPxMaxTaps;gl.uniform2fv(uTapCoords,tapCoordsArr);gl.uniform1fv(uTapTimes,tapTimesArr)};canvas.addEventListener("pointerdown",onPointerDown,{passive:!0});var raf;function loop(){raf=requestAnimationFrame(loop);var elapsed=(performance.now()-startTime)/1000;gl.uniform1f(uClock,timeOffset+elapsed*speed);gl.clear(gl.COLOR_BUFFER_BIT);gl.drawArrays(gl.TRIANGLES,0,3)}
raf=requestAnimationFrame(loop);element._danPxCtx={gl:gl,raf:raf,ro:resizeObserver,canvas:canvas,onDown:onPointerDown,program:program};element.removeAttribute("data-flickering")})}
window.dancepad_pixels=dancepad_pixels;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",dancepad_pixels)}else{dancepad_pixels()}